int main(void) {
  srand(time(NULL));
  volatile int *pixel_ctrl_ptr = (int *)0xFF203020;
  // declare other variables(not shown)
  // initialize location and direction of rectangles(not shown)
  /* set front pixel buffer to Buffer 1 */

  *(pixel_ctrl_ptr + 1) = (int)&Buffer1;  // first store the address in the
                                          // back buffer
  /* now, swap the front/back buffers, to set the front buffer location */
  wait_for_vsync();
  /* initialize a pointer to the pixel buffer, used by drawing functions */
  pixel_buffer_start = *pixel_ctrl_ptr;
  clear_screen();  // pixel_buffer_start points to the pixel buffer
                   /* set back pixel buffer to Buffer 2 */
  *(pixel_ctrl_ptr + 1) = (int)&Buffer2;
  pixel_buffer_start = *(pixel_ctrl_ptr + 1);  // we draw on the back buffer clear_screen(); //
                              // pixel_buffer_start points to the pixel buffer
  wait_for_vsync();  // swap front and back buffers on VGA vertical sync
  pixel_buffer_start = *(pixel_ctrl_ptr + 1);  // new back buffer }
  selected = 5;
  while (1) {
    /* Erase any boxes and lines that were drawn in the last iteration */
    //...
    // code for drawing the boxes and lines (not shown)
    // code for updating the locations of boxes (not shown)

   //polling keys
    volatile int *PS2_ptr = (int *)PS2_BASE;
    volatile int *LEDs = 0xFF200000;
    int PS2_data, RVALID;
    char byte1 = 0, byte2 = 0, byte3 = 0;
    *(PS2_ptr) = 0xFF;  // reset
    PS2_data = *(PS2_ptr);       // read the Data register in the PS/2 port
    RVALID = PS2_data & 0x8000;  // extract the RVALID field
    if (RVALID) {
      byte1 = byte2;
      byte2 = byte3;
      byte3 = PS2_data & 0xFF;
      if (byte3 == 0x6B ) {
        *LEDs = 1;
        if (r > 0) {  //up
          r--;
        }
      } else if (byte3 == 0x74) { //down
        *LEDs = 2;
        if (r < 3) {
          r++;
        }
      } else if (byte3 ==  0x75) {  //left
        *LEDs = 4;
        if (c > 0) {
          c--;
        }
      } else if (byte3 == 0x72) {   //right
        *LEDs = 8;
        if (c < 3) {
          c++;
        }
      } else if (byte3 == 0x5A) {   //enter pressed
        *LEDs = 16;
        selectedboxrow=r;
        selectedboxcol=c;
      } else {
        *LEDs = 0;
      }
    }
    


  // locate empty box
  for (int i = 0; i++; i < 4) {
    for (int j = 0; j++; j < 4) {
      if (board[i][j] == 0) {
        er = i;
        ec = j;
      }
    }
  }

  // up
  if ( selectedboxcol == ec && selectedboxrow == er - 1) {
    // swap
      temp = board[selectedboxrow][selectedboxcol];
      board[selectedboxrow][selectedboxcol] = board[er][ec];
      board[er][ec] = temp;
  }

  // down
  if (selectedboxcol == ec && selectedboxrow == er + 1) {
    // swap
    temp = board[selectedboxrow][selectedboxcol];
    board[er][ec] = temp;
    board[selectedboxrow][selectedboxcol] = 0;
  }

  // left
  if (selectedboxcol == ec - 1 && selectedboxrow == er) {
    // swap
    temp = board[selectedboxrow][selectedboxcol];
    board[er][ec] = temp;
    board[selectedboxrow][selectedboxcol] = 0;
  }

  // right
  if (selectedboxcol == ec + 1 && selectedboxrow == er) {
    // swap
    temp = board[selectedboxrow][selectedboxcol];
    board[er][ec] = temp;
    board[selectedboxrow][selectedboxcol] = 0;
  }

  //check if tile is in correct position, if yes, output audio 
  for (int i = 0; i++; i < 4) {
    for (int j = 0; j++; j < 4) {
      if (board[i][j] == i*4+1+j) {   // i*4+1+j gives you the tile number, eg: tile at (0,0) has number 1 
        audio_playback_mono(samples, samples_n);  //play audio
        score++;
      }
    }
  }

  draw();
	if((timer == 120) ||(timer==60)){
		sectimer =0;
	}
	if(timer !=0){
	timer = timer-1;
	sectimer++;
	}
    wait_for_vsync();  // swap front and back buffers on VGA vertical sync
    pixel_buffer_start = *(pixel_ctrl_ptr + 1);  // new back buffer }
  }
}
// code for subroutines (not shown)

void plot_pixel(int x, int y, short int line_color){
  volatile short int *one_pixel_address;

  one_pixel_address = pixel_buffer_start + (y << 10) + (x << 1);

  *one_pixel_address = line_color;
}

void clear_screen() {
  int y, x;

  for (x = 0; x < 320; x++)
    for (y = 0; y < 240; y++) plot_pixel(x, y, 0);
}

void draw_line(int x0, int y0, int x1, int y1, short int color) {
  bool is_steep = abs(y1 - y0) > abs(x1 - x0);
  int y_step;
  if (is_steep) {
    swap(&x0, &y0);
    swap(&x1, &y1);
  }
  if (x0 > x1) {
    swap(&x0, &x1);
    swap(&y0, &y1);
  }

  int deltax = x1 - x0;
  int deltay = abs(y1 - y0);
  int error = -(deltax / 2);
  int y = y0;
  if (y0 < y1) {
    y_step = 1;
  } else {
    y_step = -1;
  }

  for (int i = x0; i < x1; i++) {
    if (is_steep) {
      plot_pixel(y, i, color);
    } else {
      plot_pixel(i, y, color);
    }
    error = error + deltay;
    if (error > 0) {
      y = y + y_step;
      error = error - deltax;
    }
  }
}

void swap(int *x, int *y) {
  int temp = *x;
  *x = *y;
  *y = temp;
}

void wait_for_vsync() {
  volatile int *pixel_ctrl_ptr = (int *)0xFF203020;

  int status;

  *pixel_ctrl_ptr = 1;
  status = *(pixel_ctrl_ptr + 3);
  while ((status & 0x01) != 0) {
    status = *(pixel_ctrl_ptr + 3);
  }
}

void draw() {
  int color =0xf800;
  for(int i = 0;i<4;i++){
    for(int j = 0;j<4;j++){
      draw_boxs_background(i*57,j*57,color,board[i][j]);
      draw_each_number(board[i][j],i*57+5,j*57+5);
    }
  }
  int xcoord = 260;
  int ycoord = 10;
  for(int i=0;i<60;i++){
    for(int j=0;j<40;j++){
	  if(treeim[i][j] >59500){
		  plot_pixel(xcoord+j,ycoord+i,0);
	  }
      else if(!(treeim[i][j]>sectimer*616 || treeim[i][j]>37000)&&(timer>120)){
        plot_pixel(xcoord+j,ycoord+i,0);
      }
      else if(timer>120){
      plot_pixel(xcoord+j,ycoord+i,treeim[i][j]);
      }
    }
  }

  for(int i=0;i<60;i++){
    for(int j=0;j<40;j++){
	if(treeim[i][j] >59500){
		  plot_pixel(xcoord+j,80+i,0);
	  }
      else if(!((treeim[i][j]>sectimer*616 || treeim[i][j]>37000))&&(60<timer<120)){
        plot_pixel(xcoord+j,80+i,0);
      }
      else if(timer>60){
      plot_pixel(xcoord+j,80+i,treeim[i][j]);
      }
    }
  }

   for(int i=0;i<60;i++){
    for(int j=0;j<40;j++){
	if(treeim[i][j] >59500){
		  plot_pixel(xcoord+j,160+i,0);
	  }
     else if(!(treeim[i][j]>sectimer*616 || treeim[i][j]>37000)&&(timer<60)){
        plot_pixel(xcoord+j,160+i,0);
      }
      else{
      plot_pixel(xcoord+j,160+i,treeim[i][j]);
      }
    }
  }


}

void draw_boxs_background(int x, int y, int color,int num) {
  if(num==0){
	for(int i =0;i<50;i++){
    for(int j=0;j<50;j++){
      plot_pixel(x+i, y+j,0);
    }
  }
  }
  else{
  int xcoord, ycoord,xpo,ypo;
  xcoord = (num-1)/4;
  ycoord = (num-1)%4;
  xpo = xcoord*50;
  ypo = ycoord*50;
  for(int i =0;i<50;i++){
    for(int j=0;j<50;j++){
      plot_pixel(x+i, y+j, im[ypo+j][xpo+i]);
    }
  }
  }
}

void draw_I(int starting_point_x, int starting_point_y, int color){
  draw_line(starting_point_x,starting_point_y,starting_point_x,starting_point_y+35,color);
}

void draw_X(int starting_point_x, int starting_point_y, int color){
  draw_line(starting_point_x,starting_point_y,starting_point_x+20,starting_point_y+35,color);
  draw_line(starting_point_x+20,starting_point_y,starting_point_x,starting_point_y+35,color);
}

void draw_V(int starting_point_x, int starting_point_y,int color){
  draw_line(starting_point_x,starting_point_y,starting_point_x+10,starting_point_y+35,color);
  draw_line(starting_point_x+20,starting_point_y,starting_point_x+10,starting_point_y+35,color);
}

void draw_each_number(int number, int starting_point_x, int starting_point_y){
    int color = 0x07e0;
    selected = board[r][c];
    if(selected == number){
      color = 0x07ff;
    }
    if(number == 1||number == 2|| number ==3){
      for(int i =0;i<number;i++){
        draw_I(starting_point_x+i*5,starting_point_y,color);
      }
    }
    if(number ==4||number == 9){
     draw_I(starting_point_x,starting_point_y,color);
      if(number == 4){
        draw_V(starting_point_x+5,starting_point_y,color);
      }
      if(number == 9){
        draw_X(starting_point_x+5,starting_point_y,color);
      }
    }
    if(number == 5||number == 6|| number ==7||number ==8){
      draw_V(starting_point_x, starting_point_y,color);
      for(int i=1;i<number-5+1;i++){
        draw_I(starting_point_x+26+i*5,starting_point_y,color);
      }
    }
    if(number== 10||number == 11|| number == 12|| number==13||number == 14|| number ==15|| number == 16){
      draw_X(starting_point_x,starting_point_y,color);
      for(int i=1;i<number-10+1;i++){
        if(number!=14&&number!=15&&number!=16){
          draw_I(starting_point_x+26+i*5,starting_point_y,color);
        }
      }
      if(number == 14){
        draw_I(starting_point_x+25,starting_point_y,color);
        draw_V(starting_point_x+30,starting_point_y,color);
      }
      if(number == 15||number == 16){
        draw_V(starting_point_x+23,starting_point_y,color);
        if(number == 16){
          draw_I(starting_point_x+45,starting_point_y,color);
        }
      }
    }
}